export const useUiStore = defineStore('cultivation-fairy-girlfriend-ui', () => {
    const mobileTab = ref('story');
    const actionSection = ref('cultivation');
    const showDebug = ref(false);
    const storyLogOpen = ref(false);
    const analysisLogOpen = ref(false);
    const cloudWorldOpen = ref(false);
    const tutorialOpen = ref(false);
    const tutorialStep = ref(0);
    function openTutorial() {
        tutorialStep.value = 0;
        tutorialOpen.value = true;
    }
    function closeTutorial() {
        tutorialOpen.value = false;
    }
    function markTutorialDone() {
        tutorialOpen.value = false;
    }
    function setTutorialStep(step) {
        tutorialStep.value = Math.max(0, step);
    }
    function setMobileTab(tab) {
        mobileTab.value = tab;
    }
    function setActionSection(section) {
        actionSection.value = section;
        if (section === 'world')
            cloudWorldOpen.value = true;
    }
    function toggleDebug() {
        showDebug.value = false;
    }
    function toggleStoryLog() {
        storyLogOpen.value = !storyLogOpen.value;
    }
    function toggleAnalysisLog() {
        analysisLogOpen.value = !analysisLogOpen.value;
    }
    function openCloudWorld() {
        actionSection.value = 'world';
        cloudWorldOpen.value = true;
    }
    function closeCloudWorld() {
        cloudWorldOpen.value = false;
    }
    return {
        mobileTab,
        actionSection,
        showDebug,
        storyLogOpen,
        analysisLogOpen,
        cloudWorldOpen,
        tutorialOpen,
        tutorialStep,
        setMobileTab,
        setActionSection,
        toggleDebug,
        toggleStoryLog,
        toggleAnalysisLog,
        openCloudWorld,
        closeCloudWorld,
        openTutorial,
        closeTutorial,
        markTutorialDone,
        setTutorialStep,
    };
});
