import type { ActionFactPacket, GameSave } from './types';
import { markTimestamp } from './clock';
import { recordAssistantStoryOutput } from './narration';
import { createId, nowIso, recordDebugPacket } from './save';
import {
  buildOpeningStoryText,
  INITIAL_REALITY_BALANCE,
  OPENING_FIRST_CHARGE_COST,
  OPENING_FIRST_CHARGE_GAIN_BLOCK,
} from './staticTexts';

function buildOpeningFactPacket(save: GameSave): ActionFactPacket {
  return {
    actionId: 'opening_first_charge',
    section: 'resources',
    publicOperation: '玩家完成开场设定，并确认首充大礼包。',
    resultSummary: `开场固定事件：现实资金 -${OPENING_FIRST_CHARGE_COST}，灵石 +50，凝神香 +1，初始加护 +1。`,
    stateDelta: {
      现实资金: -OPENING_FIRST_CHARGE_COST,
      灵石: '+50',
      凝神香: '+1',
      初始加护: '+1',
    },
    frontendResult: {
      outcome: 'success',
      consumed: {
        现实资金: OPENING_FIRST_CHARGE_COST,
      },
      notes: ['开场白固定解析：首充礼包入库，隐藏解析不展示给玩家。'],
    },
    performanceHint: {
      expression: '惊讶',
      action: '捧着新出现的灵石发呆',
      portrait: save.heroine.display.formalPoseId || 'turnBack',
      chibi: save.heroine.display.chibiAnimationId || 'idleBreath',
      scene: '万剑山脉·无名溪畔',
    },
    debugOnly: true,
  };
}

export function applyOpeningStoryIfNeeded(save: GameSave): GameSave {
  if (save.onboarding.openingAppliedAtIso) return save;

  const appliedAtIso = nowIso();
  const playerName = save.player?.displayName || '{{user}}';
  const openingText = buildOpeningStoryText(playerName);
  const factPacket = buildOpeningFactPacket(save);
  const baseBalance =
    save.money.balance === 10000000 && save.money.ledger.length === 0 ? INITIAL_REALITY_BALANCE : save.money.balance;
  const chargedSave: GameSave = {
    ...save,
    money: {
      ...save.money,
      balance: Math.max(0, baseBalance - OPENING_FIRST_CHARGE_COST),
      spentTotal: save.money.spentTotal + OPENING_FIRST_CHARGE_COST,
      ledger: [
        {
          id: createId('money'),
          kind: 'payment' as const,
          label: '首充大礼包',
          amount: -OPENING_FIRST_CHARGE_COST,
          createdAtIso: appliedAtIso,
        },
        ...save.money.ledger,
      ].slice(0, 80),
    },
  };

  const assistantText = [
    '<content>',
    openingText,
    '</content>',
    '<gain>',
    OPENING_FIRST_CHARGE_GAIN_BLOCK,
    '</gain>',
    '<feedback>',
    `时间戳|${save.timestamps.cultivationWorldLabel || '万剑山脉·无名溪畔·黄昏'}`,
    '表情|惊讶',
    '动作|捧着新出现的灵石发呆',
    '立绘|turnBack',
    '场景|万剑山脉·无名溪畔',
    '状态|心境|惊讶又开心',
    '状态|伤势|无',
    '</feedback>',
  ].join('\n');

  const storySave = recordAssistantStoryOutput(chargedSave, assistantText, factPacket, {
    inputPacket: '开场白固定文本与首充隐藏解析',
  });

  return markTimestamp(
    recordDebugPacket(
      {
        ...storySave,
        onboarding: {
          ...storySave.onboarding,
          openingAppliedAtIso: appliedAtIso,
        },
      },
      {
        title: '开场白固定解析',
        body: JSON.stringify(
          {
            playerName,
            factPacket,
            gainBlock: OPENING_FIRST_CHARGE_GAIN_BLOCK,
          },
          null,
          2,
        ),
      },
    ),
    'lastStoryGeneratedAtIso',
  );
}
