function normalizeRawYaml(source: string): string {
  return String(source || '')
    .replace(/^\uFEFF/u, '')
    .replace(/\r\n/g, '\n')
    .trim();
}

function entry(
  id: string,
  kind: WorldWorkshopContentKind,
  label: string,
  tags: string[],
  yamlText: string,
): WorldWorkshopModuleEntry {
  return {
    id,
    kind,
    label,
    tags: Array.from(new Set(['官方默认', ...tags])),
    yamlText: normalizeRawYaml(yamlText),
    sourceModuleId: DEFAULT_WORLD_MODULE_ID,
  };
}

