function decodeHtmlEntity(entity: string): string {
  const map: Record<string, string> = {
    amp: '&',
    lt: '<',
    gt: '>',
    quot: '"',
    apos: "'",
    nbsp: ' ',
  };
  if (map[entity]) return map[entity];
  const decimal = entity.match(/^#(\d+)$/);
  if (decimal) return String.fromCharCode(Number(decimal[1]));
  const hex = entity.match(/^#x([0-9a-f]+)$/i);
  if (hex) return String.fromCharCode(parseInt(hex[1], 16));
  return `&${entity};`;
}

function markdownModuleToText(source: unknown): string {
  return String(source || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(?:p|div|li|h\d|pre|blockquote|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&([^;]+);/g, (_, entity: string) => decodeHtmlEntity(entity))
    .replace(/\r\n/g, '\n')
    .replace(/^\s*---\s*/g, '')
    .replace(/^\s*```[^\n]*\n?/g, '')
    .replace(/\n?```\s*$/g, '')
    .trim();
}

const heroineProfileText = markdownModuleToText(heroineProfileSource);
const openingStoryText = markdownModuleToText(openingStorySource);

export const WORLD_MODULE_WRITING_GUIDE = markdownModuleToText(worldModuleGuideSource);

export function buildHeroineProfileText(name: string): string {
  const normalizedName = name.trim() || '（占位，由玩家命名）';
  return heroineProfileText
    .replace(/\n——初始状态——[\s\S]*$/u, '')
    .replace(/姓名:\s*（占位，由玩家命名）/u, `姓名: ${normalizedName}`)
    .replace(/\{\{heroine\}\}/g, normalizedName)
    .trim();
}

export function buildOpeningStoryText(playerName: string): string {
  const normalizedName = playerName.trim() || '{{user}}';
  return openingStoryText.replace(/\{\{user\}\}/g, normalizedName).trim();
}

