function normalizeOperation(input: string): string {
  return input.trim() || '观察她当前状态';
}

function wrapContextBlock(block: EmbeddedContextBlock): string {
  const tag = block.wrapTag || `${block.tagName}_idx${block.index}`;
  if (block.preserveContent) {
    return [`<${tag}>`, block.yamlText, `</${tag}>`].join('\n');
  }
  return [
    `<${tag}>`,
    `块名: ${block.label}`,
    `模块槽: ${block.slot}`,
    `内容类型: ${block.kind}`,
    `来源: ${block.source}`,
    `用途: ${block.matchReason}`,
    '内容:',
    block.yamlText,
    `</${tag}>`,
  ].join('\n');
}

export function wrapPublicOperationForPrompt(publicOperation: string): string {
  return ['<player_action>', publicOperation, '</player_action>'].join('\n');
}

function wrapPromptSlot(slot: PromptModuleSlot, label: string, promptText: string): string {
  return [`<prompt_slot id="${slot}" label="${label}">`, promptText, '</prompt_slot>'].join('\n');
}

function wrapForMingyueQiuqingBadEnd(slotText: string): string {
  return ['<observed_piece class="设定">', slotText, '</observed_piece>'].join('\n');
}

function createPresetInjection(adapter: PromptPresetAdapter, slotText: string): EmbeddedPromptInjection {
  return {
    position: 'in_chat',
    depth: 0,
    role: 'system',
    content: adapter === 'mingyue_qiuqing_bad_end' ? wrapForMingyueQiuqingBadEnd(slotText) : slotText,
    should_scan: false,
  };
}

function inferWorldbookPlaceholderSlot(entry: { tagName: string; label: string }): PromptModuleSlot {
  const text = `${entry.tagName}\n${entry.label}`;
  if (/玩家|user|persona/i.test(text)) return 'persona_description';
  if (/性格|动态|心境|人设/.test(text)) return 'char_personality';
  if (/角色|女主|老婆|立绘|外观/.test(text)) return 'char_description';
  if (/情景|场景|开局|主线/.test(text)) return 'scenario';
  if (/世界观|境界|规则|修仙/.test(text)) return 'world_info_before';
  return 'world_info_after';
}

function splitSearchText(text: string): string[] {
  return text
    .split(/[\s,，。；;、|·:：[\]()（）{}<>《》]+/)
    .map(item => item.trim())
    .filter(item => item.length >= 2);
}

function getRecentNarrativeText(save: GameSave): string {
  return save.messages
    .slice(-8)
    .map(message => `${message.role}\n${message.text}`)
    .join('\n');
}

function getCurrentLocationText(save: GameSave): string {
  return [
    save.heroine.display.sceneLabel,
    save.heroine.growth.currentActivity.locationLabel,
    save.heroine.growth.currentActivity.section,
  ]
    .filter(Boolean)
    .join('\n');
}

function getEntryKeywords(entry: WorldWorkshopModuleEntry): string[] {
  return Array.from(new Set([entry.label, ...entry.tags, ...splitSearchText(entry.label)].filter(item => item.length >= 2)));
}

function entryMatches(entry: WorldWorkshopModuleEntry, publicOperation: string, sceneLabel: string): boolean {
  const searchText = `${publicOperation}\n${sceneLabel}`;
  const labels = [entry.label, entry.kind, ...entry.tags].filter(Boolean);
  return labels.some(label => label.length >= 2 && searchText.includes(label));
}

function entryMatchesCurrentLocation(entry: WorldWorkshopModuleEntry, currentLocationText: string): boolean {
  if (!currentLocationText || entry.kind === 'npc') return false;
  return getEntryKeywords(entry).some(keyword => currentLocationText.includes(keyword));
}

function entryMatchesNarrativeCharacter(entry: WorldWorkshopModuleEntry, narrativeText: string): boolean {
  if (entry.kind !== 'npc') return false;
  return getEntryKeywords(entry).some(keyword => narrativeText.includes(keyword));
}

interface WorldModuleCandidate {
  entry: WorldWorkshopModuleEntry;
  slot: PromptModuleSlot;
  tagName: string;
  priority: number;
  matchReason: string;
}

function worldCandidateKey(entry: WorldWorkshopModuleEntry): string {
  return `${entry.sourceModuleId || 'unknown'}:${entry.id}`;
}

function upsertWorldModuleCandidate(
  candidates: Map<string, WorldModuleCandidate>,
  candidate: WorldModuleCandidate,
): void {
  const key = worldCandidateKey(candidate.entry);
  const previous = candidates.get(key);
  if (!previous || candidate.priority > previous.priority) {
    candidates.set(key, candidate);
  }
}

function isPermanentWorldOverviewEntry(entry: WorldWorkshopModuleEntry): boolean {
  return entry.id === DEFAULT_WORLD_OVERVIEW_ENTRY_ID || entry.tags.includes('常驻激活');
}

function isContextChainEntry(entry: WorldWorkshopModuleEntry): boolean {
  return entry.kind !== 'npc' && entry.kind !== 'encounter' && entry.kind !== 'quest_seed' && entry.kind !== 'resource';
}

function entryMentionsContext(entry: WorldWorkshopModuleEntry, context: WorldWorkshopModuleEntry): boolean {
  if (worldCandidateKey(entry) === worldCandidateKey(context)) return false;
  const text = `${entry.label}\n${entry.kind}\n${entry.tags.join('\n')}\n${entry.yamlText.slice(0, 3000)}`;
  return getEntryKeywords(context).some(keyword => keyword !== entry.label && text.includes(keyword));
}

function addWorldContextChain(candidates: Map<string, WorldModuleCandidate>, selectedEntries: WorldWorkshopModuleEntry[]): void {
  const contextEntries = selectedEntries.filter(isContextChainEntry);
  for (let round = 0; round < 4; round += 1) {
    const current = Array.from(candidates.values());
    let added = false;
    for (const candidate of current) {
      for (const contextEntry of contextEntries) {
        if (candidates.has(worldCandidateKey(contextEntry))) continue;
        if (!entryMentionsContext(candidate.entry, contextEntry)) continue;
        upsertWorldModuleCandidate(candidates, {
          entry: contextEntry,
          slot: contextEntry.kind === 'settlement' || contextEntry.kind === 'secret_realm' ? 'scenario' : 'world_info_after',
          tagName: 'world_context_chain',
          priority: Math.max(650, candidate.priority - 14 - round * 6),
          matchReason: `地点父级/区域背景组合注入：${candidate.entry.label} 需要 ${contextEntry.label}`,
        });
        added = true;
      }
    }
    if (!added) break;
  }
}

function getFlagValue(flags: string[], names: string[]): string {
  const patterns = names.map(name => new RegExp(`^${name}\\s*[:：]\\s*(.+)$`));
  for (const flag of flags) {
    for (const pattern of patterns) {
      const matched = flag.match(pattern);
      if (matched?.[1]) return matched[1].trim();
    }
  }
  return '';
}

function formatEquippedItems(save: GameSave): string {
  const equipped = Object.entries(save.inventory.equipped || {}).filter(([, value]) => Boolean(value));
  if (!equipped.length) return '暂无已装备记录';
  return equipped.map(([slot, name]) => `${slot}: ${name}`).join('；');
}

function compactList(items: string[], emptyText: string, limit = 8): string {
  const filtered = items.map(item => item.trim()).filter(Boolean);
  if (!filtered.length) return emptyText;
  const visible = filtered.slice(0, limit);
  const suffix = filtered.length > limit ? `；另${filtered.length - limit}项` : '';
  return `${visible.join('；')}${suffix}`;
}

function formatResourceSummary(save: GameSave): string {
  const resources = Object.entries(save.heroine.cultivation.resources || {})
    .filter(([, value]) => Number(value) !== 0)
    .map(([key, value]) => `${key}=${value}`);
  return compactList(resources, '无额外资源', 10);
}

function formatInventorySummary(save: GameSave): string {
  const items = save.inventory.items
    .filter(item => item.count > 0)
    .slice(0, 18)
    .map(item => `${item.category}:${item.name}x${item.count}${item.unit}`);
  return compactList(items, '储物戒暂无可用物', 10);
}

function formatMethodSummary(save: GameSave): string {
  const methods = save.inventory.methods
    .slice(0, 12)
    .map(method => `${method.kind}:${method.name}/${method.grade}/${method.progressLabel}`);
  return compactList(methods, '暂无功法术法记录', 8);
}

function formatArtSummary(save: GameSave): string {
  const learned = Object.values(save.heroine.growth.arts)
    .filter(art => art.learned || art.proficiency > 0 || art.knownRecipes.length)
    .map(art => {
      const recipes = art.knownRecipes.length ? `/图谱:${art.knownRecipes.slice(0, 2).join('、')}` : '';
      return `${art.label}:${art.learned ? art.stage : '未习得'}/熟练${art.proficiency}${recipes}`;
    });
  return compactList(learned, '百艺尚未习得', 8);
}

function formatBoostSummary(save: GameSave): string {
  return compactList(
    save.heroine.growth.activeBoosts.map(boost => `${boost.label}+${Math.round(boost.successRateDelta * 100)}%/${boost.remainingUses}次`),
    '无',
    6,
  );
}

function buildHeroineRuntimeSnapshotLines(save: GameSave): string[] {
  const flags = save.heroine.cultivation.flags || [];
  const age = getFlagValue(flags, ['年龄', '年纪']) || '外貌十七八岁，实际修炼已逾百年';
  const spiritualRoot = save.heroine.cultivation.spiritualRoot || getFlagValue(flags, ['灵根']) || '黄灵根·五行俱全';
  const swordHeart = save.heroine.cultivation.swordHeart || getFlagValue(flags, ['剑心']) || '入剑';
  const growth = save.heroine.growth;
  const fishing = growth.fishing;
  return [
    '界面实时简表:',
    '  规则: 只记录当前界面已有事实；不重写性格根设定；与基础人设冲突时，以本简表代表当前存档状态。',
    `  身份|姓名=${save.heroine.name}|年龄=${age}|灵根=${spiritualRoot}|剑心=${swordHeart}`,
    `  修为|境界=${save.heroine.cultivation.realm}|进度=${save.heroine.cultivation.progress}%|小境=${growth.cultivationTrack.minorRealm}|根基=${growth.cultivationTrack.foundationStability}|瓶颈=${growth.cultivationTrack.bottleneck}|功法=${growth.cultivationTrack.currentMethod}`,
    `  状态|体力=${growth.condition.stamina}|灵力=${growth.condition.spiritualPower}|专注=${growth.condition.focus}|疲劳=${growth.condition.fatigue}|伤势=${growth.condition.injury}|丹毒=${growth.condition.danPoison}|心魔=${growth.condition.mindDemon}|心境=${growth.condition.moodTag}`,
    `  演出|头像=${save.heroine.display.avatarExpressionId}|表情=${save.heroine.display.expression}|立绘=${save.heroine.display.formalPoseId}|动作=${save.heroine.display.actionLabel}|外观=${save.heroine.display.appearanceLabel}`,
    `  位置|当前场景=${save.heroine.display.sceneLabel}|当前活动=${growth.currentActivity.label}|活动地点=${growth.currentActivity.locationLabel}|阶段=${growth.currentActivity.phase}`,
    `  资源|现实余额=${save.money.balance}|已投入=${save.money.spentTotal}|修仙资源=${formatResourceSummary(save)}`,
    `  装备|${formatEquippedItems(save)}`,
    `  背包|${formatInventorySummary(save)}`,
    `  功法术法|${formatMethodSummary(save)}`,
    `  百艺|${formatArtSummary(save)}`,
    `  钓鱼|阶段=${fishing.stage}|熟练=${fishing.proficiency}|水域=${fishing.waterArea}|鱼竿=${fishing.rodLabel}|鱼饵=${fishing.baitLabel}|总鱼获=${fishing.fishCaughtTotal}|最高=${fishing.bestCatch}`,
    `  生效加成|${formatBoostSummary(save)}`,
  ];
}

