function createWorldModuleBlocks(save: GameSave, publicOperation: string): EmbeddedContextBlock[] {
  const sceneLabel = save.heroine.display.sceneLabel;
  const currentLocationText = getCurrentLocationText(save);
  const narrativeText = [publicOperation, currentLocationText, getRecentNarrativeText(save)].join('\n');
  const selectedIds = new Set(save.worldWorkshop.selectedModuleIds);
  const selectedEntries = save.worldWorkshop.entryCache.filter(entry => selectedIds.has(entry.sourceModuleId || ''));
  const candidates = new Map<string, WorldModuleCandidate>();

  selectedEntries
    .filter(isPermanentWorldOverviewEntry)
    .forEach(entry =>
      upsertWorldModuleCandidate(candidates, {
        entry,
        slot: 'world_info_before',
        tagName: 'world_overview',
        priority: 906,
        matchReason: '常驻世界总览，用于约束势力与地点边界',
      }),
    );

  selectedEntries
    .filter(entry => entryMatchesCurrentLocation(entry, currentLocationText))
    .slice(0, 6)
    .forEach((entry, offset) =>
      upsertWorldModuleCandidate(candidates, {
        entry,
        slot: 'scenario',
        tagName: 'world_location',
        priority: 905 - offset,
        matchReason: '当前位置命中，作为当前场景资料插入',
      }),
    );

  selectedEntries
    .filter(entry => entryMatchesNarrativeCharacter(entry, narrativeText))
    .slice(0, 5)
    .forEach((entry, offset) =>
      upsertWorldModuleCandidate(candidates, {
        entry,
        slot: 'char_description',
        tagName: 'world_character',
        priority: 900 - offset,
        matchReason: '当前在场或正文提及角色命中，作为角色资料插入',
      }),
    );

  selectedEntries
    .filter(entry => entryMatches(entry, publicOperation, sceneLabel))
    .slice(0, 5)
    .forEach((entry, offset) =>
      upsertWorldModuleCandidate(candidates, {
        entry,
        slot: entry.kind === 'npc' ? 'char_description' : 'world_info_after',
        tagName: entry.kind === 'npc' ? 'world_character' : 'world_module',
        priority: 860 - offset,
        matchReason: '本轮操作或当前场景命中',
      }),
    );

  addWorldContextChain(candidates, selectedEntries);

  if (!candidates.size) {
    selectedEntries
      .filter(entry => ['continent', 'sea', 'region', 'sect'].includes(entry.kind))
      .slice(0, 3)
      .forEach((entry, offset) =>
        upsertWorldModuleCandidate(candidates, {
          entry,
          slot: 'world_info_after',
          tagName: 'world_module',
          priority: 620 - offset,
          matchReason: '已启用世界模块基础兜底',
        }),
      );
  }

  const entries = Array.from(candidates.values())
    .sort((left, right) => right.priority - left.priority)
    .slice(0, 18);

  return entries.map((candidate, offset) => ({
    id: `world_module_${candidate.entry.sourceModuleId || 'unknown'}_${candidate.entry.id}`,
    kind: 'world_module',
    slot: candidate.slot,
    tagName: candidate.tagName,
    index: 300 + offset,
    label: candidate.entry.label,
    priority: candidate.priority - offset,
    matchReason: candidate.matchReason,
    source: 'workshop',
    yamlText: [
      `${candidate.entry.kind === 'npc' ? '角色资料' : '世界模块'}:`,
      `  id: ${candidate.entry.id}`,
      `  类型: ${candidate.entry.kind}`,
      `  名称: ${candidate.entry.label}`,
      `  来源模块: ${candidate.entry.sourceModuleId || ''}`,
      `  标签: [${candidate.entry.tags.join(', ')}]`,
      `  激活依据: ${candidate.matchReason}`,
      '  内容: |',
      ...candidate.entry.yamlText.split('\n').map(line => `    ${line}`),
    ].join('\n'),
  }));
}

