import type { GameSave, HeroineState } from './types';
import { createInitialGrowthState, normalizeGrowthState } from './growthGameplay';
import { nowIso } from './save';
import { buildHeroineProfileText } from './staticTexts';

function readCultivationFlag(flags: string[] | undefined, name: string, fallback: string): string {
  const hit = (flags || []).find(flag => flag.startsWith(`${name}:`) || flag.startsWith(`${name}：`));
  if (!hit) return fallback;
  const value = hit.replace(new RegExp(`^${name}[:：]\\s*`), '').trim();
  return value || fallback;
}

export function createInitialHeroineState(): HeroineState {
  return {
    initialized: false,
    name: '仙子',
    baseProfilePlaceholder: buildHeroineProfileText('仙子'),
    display: {
      portraitId: 'heroine-placeholder',
      formalPoseId: 'turnBack',
      avatarExpressionId: 'neutral',
      chibiAnimationId: 'idleBreath',
      expression: '轻松',
      actionLabel: '任务归来',
      appearanceLabel: '白色古风修仙长裙，腰悬白玉冰蓝长剑',
      sceneLabel: '万剑山脉·无名溪畔',
      bodyStatus: '有点累',
      emotionStatus: '心情不错',
    },
    cultivation: {
      realm: '炼气期九层',
      progress: 90,
      spiritualRoot: '黄灵根·五行俱全',
      swordHeart: '入剑',
      resources: {
        灵石: 3,
        丹药: 0,
        悟性: 0,
      },
      schedule: [],
      flags: [],
    },
    growth: createInitialGrowthState(),
    dynamicProfile: {
      placeholderText: '女主动态人设占位。',
      sourceLogIds: [],
    },
  };
}

export function normalizeHeroineState(raw: unknown): HeroineState {
  const fallback = createInitialHeroineState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<HeroineState>;
  const rawFlags = Array.isArray(candidate.cultivation?.flags) ? candidate.cultivation!.flags : [];
  return {
    ...fallback,
    ...candidate,
    display: {
      ...fallback.display,
      ...candidate.display,
    },
    cultivation: {
      ...fallback.cultivation,
      ...candidate.cultivation,
      spiritualRoot:
        candidate.cultivation?.spiritualRoot || readCultivationFlag(rawFlags, '灵根', fallback.cultivation.spiritualRoot),
      swordHeart: candidate.cultivation?.swordHeart || readCultivationFlag(rawFlags, '剑心', fallback.cultivation.swordHeart),
      resources: {
        ...fallback.cultivation.resources,
        ...(candidate.cultivation?.resources || {}),
      },
      schedule: Array.isArray(candidate.cultivation?.schedule) ? candidate.cultivation!.schedule : [],
      flags: rawFlags,
    },
    growth: normalizeGrowthState(candidate.growth),
    dynamicProfile: {
      ...fallback.dynamicProfile,
      ...candidate.dynamicProfile,
      sourceLogIds: Array.isArray(candidate.dynamicProfile?.sourceLogIds) ? candidate.dynamicProfile!.sourceLogIds : [],
    },
  };
}

export function initializeHeroine(save: GameSave): GameSave {
  return {
    ...save,
    stage: 'heroine_ready',
    heroine: {
      ...save.heroine,
      initialized: true,
      baseProfilePlaceholder: buildHeroineProfileText(save.heroine.name),
      display: {
        ...save.heroine.display,
        bodyStatus: /未初始化|占位/.test(save.heroine.display.bodyStatus) ? '有点累' : save.heroine.display.bodyStatus,
        emotionStatus: /未初始化|占位/.test(save.heroine.display.emotionStatus) ? '心情不错' : save.heroine.display.emotionStatus,
      },
      cultivation: {
        ...save.heroine.cultivation,
        realm: save.heroine.cultivation.realm === '未入道' ? '炼气期九层' : save.heroine.cultivation.realm,
        progress: save.heroine.cultivation.progress === 0 ? 90 : save.heroine.cultivation.progress,
        resources: {
          ...save.heroine.cultivation.resources,
          灵石: save.heroine.cultivation.resources.灵石 || 3,
        },
      },
      growth: {
        ...save.heroine.growth,
        currentActivity: {
          ...save.heroine.growth.currentActivity,
          locationLabel:
            save.heroine.growth.currentActivity.locationLabel === '修仙游戏界面'
              ? '万剑山脉·无名溪畔'
              : save.heroine.growth.currentActivity.locationLabel,
        },
        condition: {
          ...save.heroine.growth.condition,
          fatigue: save.heroine.growth.condition.fatigue === 0 ? 12 : save.heroine.growth.condition.fatigue,
          injury: '无',
          moodTag: /未初始化|占位|平静/.test(save.heroine.growth.condition.moodTag)
            ? '心情不错'
            : save.heroine.growth.condition.moodTag,
        },
        cultivationTrack: {
          ...save.heroine.growth.cultivationTrack,
          realm: save.heroine.growth.cultivationTrack.realm === '未入道' ? '炼气期' : save.heroine.growth.cultivationTrack.realm,
          minorRealm: save.heroine.growth.cultivationTrack.minorRealm === '无' ? '九层' : save.heroine.growth.cultivationTrack.minorRealm,
          progress: save.heroine.growth.cultivationTrack.progress === 0 ? 90 : save.heroine.growth.cultivationTrack.progress,
          bottleneck:
            save.heroine.growth.cultivationTrack.bottleneck === '未触及'
              ? '筑基瓶颈'
              : save.heroine.growth.cultivationTrack.bottleneck,
          breakthroughReadiness:
            save.heroine.growth.cultivationTrack.breakthroughReadiness === 0
              ? 34
              : save.heroine.growth.cultivationTrack.breakthroughReadiness,
          currentMethod:
            save.heroine.growth.cultivationTrack.currentMethod === '未选择'
              ? '宗门基础剑法'
              : save.heroine.growth.cultivationTrack.currentMethod,
        },
      },
      dynamicProfile: {
        ...save.heroine.dynamicProfile,
        updatedAtIso: save.heroine.dynamicProfile.updatedAtIso || nowIso(),
      },
    },
  };
}

export function renameHeroine(save: GameSave, name: string): GameSave {
  const normalizedName = name.trim();
  if (!normalizedName) return save;
  return {
    ...save,
    heroine: {
      ...save.heroine,
      name: normalizedName,
      baseProfilePlaceholder: buildHeroineProfileText(normalizedName),
    },
  };
}

export function updateHeroineDisplay(save: GameSave, label: string): GameSave {
  return {
    ...save,
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        actionLabel: label || save.heroine.display.actionLabel,
      },
    },
  };
}
