export function buildPublicOperation(userInput: string): string {
  return userInput.trim();
}

export function buildStoryDisplayText(publicOperation: string): string {
  return publicOperation.replace(/^玩家操作：\s*/, '').trim() || publicOperation.trim();
}

function buildPlaceholderFactPacket(
  save: GameSave,
  publicOperation: string,
  contextMode: StoryGenerateMode = 'cultivation_world',
): ActionFactPacket {
  const realityMode = contextMode === 'reality';
  return {
    actionId: realityMode ? 'reality_free_input' : 'free_story_input',
    section: realityMode ? 'reality' : 'life',
    publicOperation,
    resultSummary: realityMode
      ? '玩家进行现实世界行动；本轮只由提示词审查现实收益是否合理，合理时允许隐藏写入现实资金。'
      : '玩家自行发言或自由行动；本轮没有界面数值结算，正文只按当前世界、女主状态和玩家话语自然回应。',
    stateDelta: {},
    performanceHint: {
      expression: save.heroine.display.expression,
      action: save.heroine.display.actionLabel,
      portrait: save.heroine.display.formalPoseId,
      chibi: save.heroine.display.chibiAnimationId,
      scene: save.heroine.display.sceneLabel,
    },
    debugOnly: true,
  };
}

function stripStoryCheckpoints(save: GameSave): GameSave {
  const withoutNestedCheckpoints = (snapshot: GameSave): GameSave => ({
    ...snapshot,
    storyCheckpoints: [],
  });
  return {
    ...save,
    storyCheckpoints: save.storyCheckpoints
      .map(checkpoint => ({
        ...checkpoint,
        beforeSave: withoutNestedCheckpoints(checkpoint.beforeSave),
        generationBaseSave: withoutNestedCheckpoints(checkpoint.generationBaseSave),
      }))
      .slice(0, 12),
  };
}

function pushStoryCheckpoint(
  save: GameSave,
  checkpoint: Omit<StoryCheckpoint, 'id' | 'createdAtIso'>,
): GameSave {
  const nextCheckpoint: StoryCheckpoint = {
    ...checkpoint,
    id: createId('story_checkpoint'),
    createdAtIso: new Date().toISOString(),
    beforeSave: stripStoryCheckpoints(checkpoint.beforeSave),
    generationBaseSave: stripStoryCheckpoints(checkpoint.generationBaseSave),
  };
  return {
    ...save,
    storyCheckpoints: [nextCheckpoint, ...save.storyCheckpoints].slice(0, 12),
  };
}

function findStoryCheckpoint(save: GameSave, assistantMessageId?: string): StoryCheckpoint | undefined {
  if (assistantMessageId) {
    return save.storyCheckpoints.find(checkpoint => checkpoint.assistantMessageId === assistantMessageId);
  }
  return save.storyCheckpoints[0];
}

export function buildGenerationInputPacketWithFact(
  save: GameSave,
  task: GenerateTaskKind,
  publicOperation: string,
  factPacket: ActionFactPacket,
  contextMode: StoryGenerateMode = 'cultivation_world',
): string {
  const embeddedPrompt = buildEmbeddedPromptAssembly(save, {
    task,
    publicOperation,
    factPacket,
    contextMode,
  });
  return JSON.stringify(
    {
      task,
      contextMode,
      publicOperation,
      taggedUserInput: wrapPublicOperationForPrompt(publicOperation),
      rule:
        '正文公开输入只写本轮操作；结算步骤、状态旧值新值和演出建议只进入隐藏结算记录；已登记奖励不重复写入 <gain>，只有结算记录之外的新获得才写短行隐藏记录；正文末尾可写 <feedback> 隐藏演出块。',
      hiddenFactPacket: factPacket,
      embeddedPrompt: {
        mode: contextMode === 'reality' ? 'frontend_reality_audit' : 'frontend_builtin_worldbook',
        contextMode,
        adapter: embeddedPrompt.adapter,
        modules: embeddedPrompt.modules.map(module => ({
          slot: module.slot,
          label: module.label,
          blockIds: module.blocks.map(block => block.id),
        })),
        matchedBlocks: embeddedPrompt.blocks.map(block => ({
          id: block.id,
          label: block.label,
          kind: block.kind,
          slot: block.slot,
          source: block.source,
          matchReason: block.matchReason,
        })),
        promptText: embeddedPrompt.promptText,
        injectionText: embeddedPrompt.injectionText,
        tavernGenerateConfig: buildTavernPresetGenerateConfig(save, {
          task,
          publicOperation,
          factPacket,
          contextMode,
        }),
      },
      timestamps: save.timestamps,
      heroine: {
        rightPanelDisplay: save.heroine.display,
        cultivation: save.heroine.cultivation,
        growth: save.heroine.growth,
        dynamicProfile: save.heroine.dynamicProfile.placeholderText,
      },
      inventory: save.inventory,
      playerAnalysis: save.playerAnalysis.placeholderText,
      recentMessages: save.messages.slice(-8),
    },
    null,
    2,
  );
}

export function buildGenerationInputPacket(
  save: GameSave,
  task: GenerateTaskKind,
  userInput: string,
  contextMode: StoryGenerateMode = 'cultivation_world',
): string {
  const publicOperation = buildPublicOperation(userInput);
  return buildGenerationInputPacketWithFact(
    save,
    task,
    publicOperation,
    buildPlaceholderFactPacket(save, publicOperation, contextMode),
    contextMode,
  );
}

function packetHasContent(packet: ParsedAcquisitionPacket): boolean {
  return Boolean(
    packet.items?.length ||
      packet.methods?.length ||
      packet.equip?.length ||
      Object.keys(packet.resources || {}).length ||
      packet.notes?.length,
  );
}

function normalizeRewardKey(value: string): string {
  return value.trim().toLowerCase();
}

function collectRegisteredRewardKeys(factPacket?: ActionFactPacket): Set<string> {
  const result = new Set<string>();
  for (const key of Object.keys(factPacket?.frontendResult?.rewards || {})) {
    result.add(normalizeRewardKey(key));
  }
  for (const key of Object.keys(factPacket?.frontendResult?.materialPurchases || {})) {
    result.add(normalizeRewardKey(key));
  }
  return result;
}

function isFrontendAuthoritativeEquipAction(factPacket?: ActionFactPacket): boolean {
  return factPacket?.section === 'equipment' || factPacket?.section === 'wardrobe';
}

function filterAlreadyRegisteredAcquisitions(
  packet: ParsedAcquisitionPacket,
  factPacket?: ActionFactPacket,
): { packet: ParsedAcquisitionPacket; removed: string[] } {
  const rewardKeys = collectRegisteredRewardKeys(factPacket);
  const authoritativeEquip = isFrontendAuthoritativeEquipAction(factPacket);
  const authoritativeSlot = normalizeRewardKey(String(factPacket?.stateDelta?.槽位 || ''));
  const authoritativeItem = normalizeRewardKey(String(factPacket?.stateDelta?.当前物品 || ''));

  const removed: string[] = [];
  const items = (packet.items || []).filter(item => {
    const duplicated = rewardKeys.has(normalizeRewardKey(item.name));
    if (duplicated) removed.push(`物品:${item.name}`);
    return !duplicated;
  });
  const methods = (packet.methods || []).filter(method => {
    const duplicated = rewardKeys.has(normalizeRewardKey(method.name));
    if (duplicated) removed.push(`功法:${method.name}`);
    return !duplicated;
  });
  const resources = Object.entries(packet.resources || {}).reduce<Record<string, number>>((result, [key, value]) => {
    const duplicated = rewardKeys.has(normalizeRewardKey(key));
    if (duplicated) removed.push(`资源:${key}`);
    if (!duplicated) result[key] = value;
    return result;
  }, {});
  const equip = (packet.equip || []).filter(change => {
    const duplicated =
      authoritativeEquip ||
      (normalizeRewardKey(change.slot) === authoritativeSlot && normalizeRewardKey(change.name) === authoritativeItem);
    if (duplicated) removed.push(`装备:${change.slot}/${change.name}`);
    return !duplicated;
  });

  return {
    packet: {
      ...packet,
      items,
      methods,
      equip,
      resources,
      notes: removed.length ? [...(packet.notes || []), `已过滤重复登记: ${removed.join('、')}`] : packet.notes,
    },
    removed,
  };
}

function applyParsedResources(save: GameSave, packet: ParsedAcquisitionPacket): GameSave {
  const resources = packet.resources || {};
  if (!Object.keys(resources).length) return save;
  const realityEntries = Object.entries(resources).filter(([key]) => /现实资金|现实余额|现金|人民币|钱/.test(key));
  const realityIncome = realityEntries.reduce((sum, [, value]) => sum + Math.max(0, Number(value) || 0), 0);
  const cultivationResources = Object.entries(resources).filter(
    ([key]) => !/现实资金|现实余额|现金|人民币|钱/.test(key),
  );
  return {
    ...save,
    money: realityIncome
      ? {
          ...save.money,
          balance: save.money.balance + realityIncome,
          ledger: [
            {
              id: createId('money'),
              kind: 'earning' as const,
              label: '现实行动收入',
              amount: realityIncome,
              createdAtIso: new Date().toISOString(),
            },
            ...save.money.ledger,
          ].slice(0, 80),
        }
      : save.money,
    heroine: {
      ...save.heroine,
      cultivation: {
        ...save.heroine.cultivation,
        resources: cultivationResources.reduce<Record<string, number>>(
          (result, [key, value]) => ({
            ...result,
            [key]: (result[key] || 0) + value,
          }),
          { ...save.heroine.cultivation.resources },
        ),
      },
    },
  };
}

function applyParsedRecipeDiscoveries(save: GameSave, packet: ParsedAcquisitionPacket): GameSave {
  if (!packet.methods?.length) return save;
  return {
    ...save,
    heroine: {
      ...save.heroine,
      growth: applyRecipeDiscoveriesToGrowth(save.heroine.growth, packet.methods),
    },
  };
}

function normalizeFeedbackValue(value: unknown, fallback: string): string {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

export function extractVisibleStoryContent(assistantText: string): string {
  const contentMatches = Array.from(assistantText.matchAll(/<content\b[^>]*>([\s\S]*?)(?:<\/content>|$)/gi));
  if (contentMatches.length > 0) {
    return contentMatches
      .map(match => stripHiddenStoryBlocks(match[1]).trim())
      .filter(Boolean)
      .join('\n\n');
  }

  return stripHiddenStoryBlocks(assistantText).trim();
}

export function assertValidAssistantStoryText(assistantText: string): void {
  if (!/<content\b[^>]*>/i.test(assistantText)) {
    throw Error('本轮回复缺少 <content> 正文块，已拦截：不会写入正文、不会推进记忆、不会改动存档。请重ROLL生成。');
  }
  if (!extractVisibleStoryContent(assistantText).trim()) {
    throw Error('本轮 <content> 正文为空，已拦截：不会写入正文、不会推进记忆、不会改动存档。请重ROLL生成。');
  }
}

function stripHiddenStoryBlocks(text: string): string {
  return text
    .replace(/<(?:think|thinking|metacognition|time|analysis|debug|prompt|frontend_parse|frontend_feedback|story_feedback|feedback|gain)(?:\s[^>]*)?>[\s\S]*?<\/(?:think|thinking|metacognition|time|analysis|debug|prompt|frontend_parse|frontend_feedback|story_feedback|feedback|gain)>/gi, '')
    .replace(/\[metacognition\][\s\S]*?<\/thinking>/gi, '')
    .replace(/\[metacognition\][\s\S]*?(?=<content\b|<time\b|$)/gi, '')
    .replace(/```(?:thinking|think|metacognition|analysis)[\s\S]*?```/gi, '')
    .replace(/<\/?(?:content|think|thinking|metacognition|time|analysis|debug|prompt|frontend_parse|frontend_feedback|story_feedback|feedback|gain)(?:\s[^>]*)?>/gi, '')
    .trim();
}

function createFallbackFeedbackMeta(save: GameSave, factPacket?: ActionFactPacket): StoryFeedbackMeta {
  return {
    timestamp: save.timestamps.realityIso || new Date().toISOString(),
    expression: factPacket?.performanceHint.expression || save.heroine.display.expression,
    action: factPacket?.performanceHint.action || save.heroine.display.actionLabel,
    portrait: factPacket?.performanceHint.portrait || save.heroine.display.formalPoseId,
    chibi: factPacket?.performanceHint.chibi || save.heroine.display.chibiAnimationId,
    scene: factPacket?.performanceHint.scene || save.heroine.display.sceneLabel,
    statusDelta: {},
  };
}

function parseFeedbackLines(raw: string, fallback: StoryFeedbackMeta): StoryFeedbackMeta {
  const meta: StoryFeedbackMeta = {
    ...fallback,
    statusDelta: { ...fallback.statusDelta },
    rawHiddenParse: raw,
  };
  const keyMap: Record<string, keyof Pick<StoryFeedbackMeta, 'timestamp' | 'expression' | 'action' | 'portrait' | 'chibi' | 'scene'>> = {
    时间戳: 'timestamp',
    时间: 'timestamp',
    表情: 'expression',
    心情表情: 'expression',
    动作: 'action',
    行动: 'action',
    立绘: 'portrait',
    姿势立绘: 'portrait',
    场景: 'scene',
    地点: 'scene',
  };

  raw
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean)
    .forEach(line => {
      const parts = line.includes('|') ? line.split('|').map(part => part.trim()) : line.split(/[:：]/).map(part => part.trim());
      if (parts.length < 2) return;
      const key = parts[0];
      if (key === '状态' && parts.length >= 3) {
        meta.statusDelta[parts[1]] = parts.slice(2).join('|');
        return;
      }
      const mappedKey = keyMap[key];
      if (mappedKey) {
        meta[mappedKey] = parts.slice(1).join('|');
        return;
      }
      if (/状态|心境|心绪|情绪|伤势|身体|体况/.test(key)) {
        meta.statusDelta[key] = parts.slice(1).join('|');
      }
    });

  return meta;
}

function parseStoryFeedbackBlock(
  assistantText: string,
  save: GameSave,
  factPacket?: ActionFactPacket,
): { visibleText: string; meta?: StoryFeedbackMeta; rawBlock?: string; error?: string } {
  const blockPattern = /<(?:frontend_feedback|story_feedback|feedback)(?:\s[^>]*)?>([\s\S]*?)<\/(?:frontend_feedback|story_feedback|feedback)>/i;
  const matched = assistantText.match(blockPattern);
  if (!matched) return { visibleText: assistantText };
  const rawBlock = matched[0];
  const rawContent = matched[1].trim();
  const fallback = createFallbackFeedbackMeta(save, factPacket);

  try {
    const parsed = rawContent.startsWith('{')
      ? (() => {
          const json = JSON.parse(rawContent) as Partial<StoryFeedbackMeta>;
          return {
            ...fallback,
            ...json,
            statusDelta: {
              ...fallback.statusDelta,
              ...(json.statusDelta || {}),
            },
            rawHiddenParse: rawContent,
          };
        })()
      : parseFeedbackLines(rawContent, fallback);
    const meta: StoryFeedbackMeta = {
      ...parsed,
      timestamp: normalizeFeedbackValue(parsed.timestamp, fallback.timestamp),
      expression: normalizeFeedbackValue(parsed.expression, fallback.expression),
      action: normalizeFeedbackValue(parsed.action, fallback.action),
      portrait: normalizeFeedbackValue(parsed.portrait, fallback.portrait),
      chibi: fallback.chibi,
      scene: normalizeFeedbackValue(parsed.scene, fallback.scene),
      statusDelta: parsed.statusDelta || {},
      rawHiddenParse: rawContent,
    };
    return {
      visibleText: assistantText.replace(rawBlock, '').trim(),
      meta,
      rawBlock,
    };
  } catch (error) {
    return {
      visibleText: assistantText.replace(rawBlock, '').trim(),
      rawBlock,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

function applyStoryFeedbackMeta(save: GameSave, meta: StoryFeedbackMeta): GameSave {
  const status = meta.statusDelta || {};
  const bodyStatus =
    String(status['伤势'] || status['身体'] || status['体况'] || '').trim() || save.heroine.display.bodyStatus;
  const emotionStatus =
    String(status['心境'] || status['心绪'] || status['情绪'] || status['心情'] || '').trim() || save.heroine.display.emotionStatus;
  const formalPoseId = resolveHeroineFormalPoseId(meta.portrait || save.heroine.display.formalPoseId);
  const avatarExpressionId = resolveHeroineAvatarExpressionId(meta.expression || save.heroine.display.avatarExpressionId);
  return {
    ...save,
    lastStoryFeedbackMeta: meta,
    heroine: {
      ...save.heroine,
      display: {
        ...save.heroine.display,
        expression: meta.expression,
        actionLabel: meta.action,
        formalPoseId,
        avatarExpressionId,
        chibiAnimationId: meta.chibi,
        sceneLabel: meta.scene,
        bodyStatus,
        emotionStatus,
      },
      growth: {
        ...save.heroine.growth,
        condition: {
          ...save.heroine.growth.condition,
          injury: bodyStatus,
          moodTag: emotionStatus,
        },
      },
    },
  };
}

async function requestStoryText(
  save: GameSave,
  publicOperation: string,
  factPacket: ActionFactPacket,
  contextMode: StoryGenerateMode = 'cultivation_world',
): Promise<string> {
  const config = buildTavernPresetGenerateConfig(save, {
    task: 'story',
    publicOperation,
    factPacket,
    contextMode,
  });

  if (typeof generate === 'function') {
    return generate(config);
  }

  return `<content>\n正文反馈占位：已接收${buildStoryDisplayText(publicOperation)}。\n</content>`;
}

function buildFactPacketPreview(factPacket?: ActionFactPacket): string | undefined {
  if (!factPacket) return undefined;
  return JSON.stringify(
    {
      actionId: factPacket.actionId,
      section: factPacket.section,
      publicOperation: factPacket.publicOperation,
      resultSummary: factPacket.resultSummary,
      stateDelta: factPacket.stateDelta,
      frontendResult: factPacket.frontendResult,
      performanceHint: factPacket.performanceHint,
    },
    null,
    2,
  );
}

function buildPlayerStoryMeta(factPacket: ActionFactPacket, displayText = buildStoryDisplayText(factPacket.publicOperation)): StoryMessageMeta {
  return {
    publicOperation: factPacket.publicOperation,
    displayText,
    actionId: factPacket.actionId,
    section: factPacket.section,
    resultSummary: factPacket.resultSummary,
    factPacket,
    factPacketPreview: buildFactPacketPreview(factPacket),
  };
}

interface AssistantStoryRecordOptions {
  inputPacket?: string;
}

function getLatestMessageId(save: GameSave, role: GameSave['messages'][number]['role']): string | undefined {
  return [...save.messages].reverse().find(message => message.role === role)?.id;
}

export function recordAssistantStoryOutput(
  save: GameSave,
  assistantText: string,
  factPacket?: ActionFactPacket,
  options: AssistantStoryRecordOptions = {},
): GameSave {
  assertValidAssistantStoryText(assistantText);
  const parseResult = extractHiddenAcquisitionPacket(assistantText);
  const feedbackResult = parseStoryFeedbackBlock(parseResult.visibleText, save, factPacket);
  let nextSave = save;
  const filteredResult = parseResult.packet ? filterAlreadyRegisteredAcquisitions(parseResult.packet, factPacket) : null;

  if (filteredResult?.packet && packetHasContent(filteredResult.packet)) {
    nextSave = applyParsedRecipeDiscoveries(
      applyParsedResources(
        {
          ...nextSave,
          inventory: applyParsedAcquisitionPacket(nextSave.inventory, filteredResult.packet, parseResult.rawBlock),
        },
        filteredResult.packet,
      ),
      filteredResult.packet,
    );
  } else if (parseResult.error && parseResult.rawBlock) {
    nextSave = {
      ...nextSave,
      inventory: recordInventoryParseError(nextSave.inventory, parseResult.rawBlock, parseResult.error),
    };
  }

  if (feedbackResult.meta) {
    nextSave = applyStoryFeedbackMeta(nextSave, feedbackResult.meta);
  }

  const visibleStoryText = extractVisibleStoryContent(feedbackResult.visibleText);
  const storyMeta: StoryMessageMeta = {
    publicOperation: factPacket?.publicOperation,
    actionId: factPacket?.actionId,
    section: factPacket?.section,
    resultSummary: factPacket?.resultSummary,
    factPacket,
    factPacketPreview: buildFactPacketPreview(factPacket),
    inputPacket: options.inputPacket ? '完整正文生成包已写入调试记录。' : undefined,
    rawAssistantText: assistantText,
    visibleText: visibleStoryText,
    hiddenGainRaw: parseResult.rawBlock,
    hiddenGainError: parseResult.error,
    hiddenFeedbackRaw: feedbackResult.rawBlock,
    hiddenFeedbackError: feedbackResult.error,
    feedbackMeta: feedbackResult.meta,
    removedDuplicatedRewards: filteredResult?.removed || [],
  };
  nextSave = recordMessage(nextSave, 'assistant', 'assistant', visibleStoryText || '正文反馈已返回，隐藏解析块已移除。', storyMeta);

  if (parseResult.rawBlock || parseResult.error || feedbackResult.rawBlock || feedbackResult.error) {
    nextSave = recordDebugPacket(nextSave, {
      title: '正文隐藏解析块',
      body: JSON.stringify(
        {
          rawBlock: parseResult.rawBlock,
          parsed: parseResult.packet,
          filtered: filteredResult?.packet,
          removedDuplicatedRewards: filteredResult?.removed || [],
          error: parseResult.error,
          feedbackRawBlock: feedbackResult.rawBlock,
          feedbackMeta: feedbackResult.meta,
          feedbackError: feedbackResult.error,
          visibleStoryText,
        },
        null,
        2,
      ),
    });
  }

  return nextSave;
}

export async function generateStoryPlaceholder(
  save: GameSave,
  userInput: string,
  contextMode: StoryGenerateMode = 'cultivation_world',
): Promise<GameSave> {
  const trimmed = userInput.trim();
  if (!trimmed) throw Error('正文输入不能为空。');

  const publicOperation = buildPublicOperation(trimmed);
  const factPacket = buildPlaceholderFactPacket(save, publicOperation, contextMode);
  const inputPacket = buildGenerationInputPacketWithFact(save, 'story', publicOperation, factPacket, contextMode);
  const assistantText = await requestStoryText(save, publicOperation, factPacket, contextMode);
  return recordGeneratedStoryExchange({
    beforeSave: save,
    generationBaseSave: save,
    factPacket,
    assistantText,
    inputPacket,
    contextMode,
  });
}

interface GeneratedStoryExchangeRequest {
  beforeSave: GameSave;
  generationBaseSave: GameSave;
  factPacket: ActionFactPacket;
  assistantText: string;
  inputPacket: string;
  contextMode: StoryGenerateMode;
}

async function recordGeneratedStoryExchange(request: GeneratedStoryExchangeRequest): Promise<GameSave> {
  const { beforeSave, generationBaseSave, factPacket, assistantText, inputPacket, contextMode } = request;
  const displayText = buildStoryDisplayText(factPacket.publicOperation);
  const withUser = recordMessage(generationBaseSave, 'player', 'user', displayText, buildPlayerStoryMeta(factPacket, displayText));
  const userMessageId = getLatestMessageId(withUser, 'user');
  const storySave = await advancePersonaWorkflowsIfNeeded(
    recordAssistantStoryOutput(
      {
        ...withUser,
        onlineRealm: recordCooperativePublicOperation(generationBaseSave.onlineRealm, factPacket.publicOperation),
      },
      assistantText,
      factPacket,
      { inputPacket },
    ),
  );
  const assistantMessageId = getLatestMessageId(storySave, 'assistant');
  const withCheckpoint = pushStoryCheckpoint(storySave, {
    userMessageId,
    assistantMessageId,
    publicOperation: factPacket.publicOperation,
    displayText,
    contextMode,
    factPacket,
    beforeSave,
    generationBaseSave,
  });
  return markTimestamp(
    recordDebugPacket(withCheckpoint, {
      title: '正文生成输入包',
      body: inputPacket,
    }),
    'lastStoryGeneratedAtIso',
  );
}

export async function generateStoryForResolvedAction(
  beforeSave: GameSave,
  generationBaseSave: GameSave,
  factPacket: ActionFactPacket,
): Promise<GameSave> {
  const inputPacket = buildGenerationInputPacketWithFact(generationBaseSave, 'story', factPacket.publicOperation, factPacket);
  const assistantText = await requestStoryText(generationBaseSave, factPacket.publicOperation, factPacket);
  return recordGeneratedStoryExchange({
    beforeSave,
    generationBaseSave,
    factPacket,
    assistantText,
    inputPacket,
    contextMode: 'cultivation_world',
  });
}

export async function rerollStoryCheckpoint(save: GameSave, assistantMessageId?: string): Promise<GameSave> {
  const checkpoint = findStoryCheckpoint(save, assistantMessageId);
  if (!checkpoint) throw Error('没有可重ROLL的正文记录。');
  const inputPacket = buildGenerationInputPacketWithFact(
    checkpoint.generationBaseSave,
    'story',
    checkpoint.factPacket.publicOperation,
    checkpoint.factPacket,
    checkpoint.contextMode,
  );
  const assistantText = await requestStoryText(
    checkpoint.generationBaseSave,
    checkpoint.factPacket.publicOperation,
    checkpoint.factPacket,
    checkpoint.contextMode,
  );
  return recordGeneratedStoryExchange({
    beforeSave: checkpoint.beforeSave,
    generationBaseSave: checkpoint.generationBaseSave,
    factPacket: checkpoint.factPacket,
    assistantText,
    inputPacket,
    contextMode: checkpoint.contextMode,
  });
}

export function rollbackStoryCheckpoint(save: GameSave, assistantMessageId?: string): GameSave {
  const checkpoint = findStoryCheckpoint(save, assistantMessageId);
  if (!checkpoint) throw Error('没有可回退的正文记录。');
  return recordDebugPacket(checkpoint.beforeSave, {
    title: '正文楼层已回退',
    body: JSON.stringify(
      {
        assistantMessageId: checkpoint.assistantMessageId,
        publicOperation: checkpoint.publicOperation,
        displayText: checkpoint.displayText,
      },
      null,
      2,
    ),
  });
}
