function normalizeRawText(source: string): string {
  return String(source || '')
    .replace(/^\uFEFF/u, '')
    .replace(/\r\n/g, '\n')
    .trim();
}

function fixedWorldBlock(
  id: string,
  wrapTag: string,
  index: number,
  label: string,
  yamlText: string,
  priority: number,
): EmbeddedContextBlock {
  return {
    id,
    kind: 'worldbook_placeholder',
    slot: 'world_info_before',
    tagName: wrapTag.replace(/_id\d+$/, ''),
    wrapTag,
    index,
    label,
    yamlText: normalizeRawText(yamlText),
    preserveContent: true,
    priority,
    matchReason: '阴阳大陆基础设定，每轮固定内置注入',
    source: 'built_in',
  };
}

function fixedRuleBlock(
  id: string,
  wrapTag: string,
  index: number,
  label: string,
  yamlText: string,
  priority: number,
): EmbeddedContextBlock {
  return {
    ...fixedWorldBlock(id, wrapTag, index, label, yamlText, priority),
    slot: 'world_info_after',
  };
}

