export function buildFixedWorldviewPreview(): string {
  return FIXED_WORLDVIEW_BLOCKS.map(block => {
    const tag = block.wrapTag || `${block.tagName}_idx${block.index}`;
    return [`<${tag}>`, block.yamlText, `</${tag}>`].join('\n');
  }).join('\n\n');
}
